SELECT cd.cd_gender, p.p_promo_name, SUM(ss.ss_net_paid) AS total_net_paid, COUNT(DISTINCT ss.ss_item_sk) AS distinct_items_sold FROM store_sales ss JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk JOIN promotion p ON ss.ss_promo_sk = p.p_promo_sk WHERE cd.cd_education_status = 'Advanced Degree     ' AND p.p_discount_active = 'N' AND ss.ss_sold_date_sk BETWEEN 2451831 AND 2451471 GROUP BY cd.cd_gender, p.p_promo_name ORDER BY total_net_paid DESC
